    }
    int counter = 0;
    vector<int> ans;
    int kind, x;
    while (scanf("%d %d", &kind, &x) == 2) {
        if (kind == 0) {
            int start = -1;
            for (int i = 0; i + x <= n && start < 0; i += 8) {
                bool ok = true;
                for (int j = i; j < i + x && ok; j++) ok = cells[j] == 0;
                if (ok) start = i;
            }
            if (start >= 0) {
                counter++;
                for (int j = start; j < start + x; j++) cells[j] = counter;
            }
