import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), q = nextInt();
        // 0 = free, -1 = initially occupied, positive = allocation ID.
        int[] cells = new int[n];
        for (int i = 0; i < n; i++) cells[i] = nextInt() != 0 ? -1 : 0;
        int counter = 0;
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
            int kind = nextInt(), x = nextInt();
            int res;
            if (kind == 0) {
                int start = -1;
                for (int i = 0; i + x <= n && start < 0; i += 8) {
                    boolean ok = true;
                    for (int j = i; j < i + x && ok; j++) ok = cells[j] == 0;
                    if (ok) start = i;
                }
                if (start >= 0) {
                    counter++;
                    for (int j = start; j < start + x; j++) cells[j] = counter;
                }
                res = start;
            } else {
                int removed = 0;
                for (int i = 0; i < n; i++)
                    if (cells[i] == x) {
                        cells[i] = 0;
                        removed++;
                    }
                res = removed > 0 ? removed : -1;
            }
            if (t > 0) sb.append(' ');
            sb.append(res);
        }
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	// 0 = free, -1 = initially occupied, positive = allocation ID.
	cells := make([]int, n)
	for i := range cells {
		if nextInt() != 0 {
			cells[i] = -1
		}
	}
	counter := 0
	out := make([]string, 0, q)
	for t := 0; t < q; t++ {
		kind, x := int(nextInt()), int(nextInt())
		res := -1
		if kind == 0 {
			for i := 0; i+x <= n && res < 0; i += 8 {
				ok := true
				for j := i; j < i+x && ok; j++ {
					ok = cells[j] == 0
				}
				if ok {
					res = i
				}
			}
			if res >= 0 {
				counter++
				for j := res; j < res+x; j++ {
					cells[j] = counter
				}
			}
		} else {
			removed := 0
			for i := range cells {
				if cells[i] == x {
					cells[i] = 0
					removed++
				}
			}
			if removed > 0 {
				res = removed
			}
		}
		out = append(out, strconv.Itoa(res))
	}
	fmt.Println(strings.Join(out, " "))
}
